#### 90\. 子集 II
(https://leetcode.cn/problems/subsets-ii/) 类似 [[#47. 全排列 II|47. 全排列 II]] ，去重模板做法
同 [[#LCR 079. 子集|LCR 079. 子集]]，使用 unordered_set 的话是多余的
```cpp
struct VectorHash {
	size_t operator()(const vector<int>& other) const {
		size_t seed = 0;
		for(int i = 0; i < other.size(); i++) {
			seed ^= (std::hash<int>{}(other[i]) << i);
		}
		return seed;
	}
};

class Solution {
	using Records = unordered_set<vector<int>, VectorHash>;

	Records records;

	void traceback(vector<int>& nums, vector<int>& path, int startIndex) {
		for(int i = startIndex; i < nums.size(); i++) {
			if((i > startIndex) && (nums[i] == nums[i - 1])) {
				continue;
			}
			path.emplace_back(nums[i]);
			records.insert(path);
			traceback(nums, path, i + 1);
			path.pop_back();
		}
	}

  public:
	vector<vector<int>> subsetsWithDup(vector<int>& nums) {
		sort(nums.begin(), nums.end());
        vector<int> path;
		traceback(nums, path, 0);
		vector<vector<int>> result(records.begin(), records.end());
        result.insert({});
		return result;
	}
};
```
因为经过 `if((startIndex <= nums.size() - 2) && (nums[i] == nums[i + 1]))` 剪枝的回溯树是没有重复节点的，所以完全可以使用vector
```cpp
class Solution {
    vector<int> path;
    vector<vector<int>> result;
    void traceBack(vector<int>& nums, int startIndex, vector<bool>& visited) {
        result.push_back(path);
        for (int i = startIndex;i < nums.size();i++) {
            if (i && nums[i] == nums[i - 1] && visited[i - 1] == false) {
                continue;
            }
            path.push_back(nums[i]);
            visited[i] = true;
            traceBack(nums, i + 1, visited);
            path.pop_back();
            visited[i] = false;
        }
    }
public:
    vector<vector<int>> subsetsWithDup(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        vector<bool> visited(nums.size(), false);
        traceBack(nums, 0, visited);
        return result;
    }
};
```
其中：
-   `used[i - 1] == true`，说明同⼀树枝 `candidates[i - 1]` 使⽤过
-   `used[i - 1] == false`，说明同⼀树层 `candidates[i - 1]` 使⽤过
-   Sort 是为了辨别出重复元素并且使 used 数组有意义，在 `nums[i] == nums[i - 1]` 的情况下 `used[i-1］` 就表示重复元素的使用情况
-   最重要的是有不能漏掉元素不比较，所以 i 必须>0，放在 if 条件最前面

